    const inverse = (((init - fin) / fin) * 100).toFixed(2);
    const isPositive = delta >= 0;
    return {
      deltaVal: (isPositive ? '+$' : '-$') + Math.abs(delta).toFixed(2),
      pctChange: (isPositive ? '+' : '') + pct + '%',
