    }

    const n = arr.length;
    const sum = arr.reduce((acc, val) => acc + val, 0);
    const mean = sum / n;

    // Median
    const mid = Math.floor(n / 2);
    const median = n % 2 !== 0 ? arr[mid] : (arr[mid - 1] + arr[mid]) / 2;

