    const variance = n > 1 ? arr.reduce((acc, val) => acc + Math.pow(val - mean, 2), 0) / (n - 1) : 0;
    const stdDev = Math.sqrt(variance);

    // Quartiles
    const q1 = arr[Math.floor(n * 0.25)];
    const q3 = arr[Math.floor(n * 0.75)];
    const iqr = q3 - q1;

