    if (mw <= 0 || volMl <= 0) {
      return { molarity: '0.000', moles: '0.000', osmolarity: '0.00' };
    }
    const moles = mass / mw;
    const liters = volMl / 1000;
    const molarity = moles / liters;
    const osmolarity = molarity * 2; // NaCl i=2
    return {
      molarity: molarity.toFixed(3),
      moles: moles.toFixed(3),
