'use client';

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Link from 'next/link';
import Header from '../../components/Header';
import { getCurrentTheme, toggleTheme } from '../../lib/theme';

// --- Preset Data ---
interface ToolItem {
